def total_cost(prices):
    total = sum(prices)
    if total > 10:
        cheapest = min(prices)
        total = total - cheapest
    elif total > 5:
        total = total * 0.9
    return round(total, 2)

print(total_cost([2.0, 2.0, 2.0]))        # expect 5.40 (10% off £6)
